using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;
namespace FashionFit {
 // Explicit command-line opt-in. Never acquires controller ownership in normal play.
 public sealed class PoseMaterialPlayerVerification:MonoBehaviour {
  [Serializable] sealed class Result {public string status="passed",scope="Exported Windows desktop player, injected grab owners and real frame/PhysX updates; no physical HMD test";public int checks,exceptions;public bool fixedPhysics,defaultsDressed,headFollow,twoHandHat,independentRelease,gravity,hatRecovery,twoHandCloth,clothRecovery;public float dropM,hatOffset,hatRecovered,clothError,clothRecovered,meanFrameMs,p95FrameMs;public double maxPoseUpdateMs;}
  string output;FashionFitApp app;Result result=new Result();readonly List<float> times=new List<float>();
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Install(){var args=Environment.GetCommandLineArgs();for(int i=0;i<args.Length-1;i++)if(args[i]=="-fashionPoseMaterialVerify"){var v=new GameObject("Pose material opt-in verification").AddComponent<PoseMaterialPlayerVerification>();v.output=args[i+1];break;}}
  void Check(bool ok,string label){result.checks++;if(!ok)throw new InvalidOperationException(label);}
  void Log(string a,string b,LogType t){if(t==LogType.Error||t==LogType.Exception)result.exceptions++;}
  IEnumerator Start(){Application.runInBackground=true;Directory.CreateDirectory(output);Application.logMessageReceived+=Log;var scenario=Scenario();while(true){object next=null;bool more=false;Exception failure=null;try{more=scenario.MoveNext();if(more)next=scenario.Current;}catch(Exception e){failure=e;}if(failure!=null){result.status="failed";File.WriteAllText(Path.Combine(output,"failure.txt"),failure.ToString());Save();Application.Quit(1);yield break;}if(!more)break;yield return next;}Save();Application.Quit(0);}
  IEnumerator Scenario(){double deadline=Time.realtimeSinceStartupAsDouble+40;while(!app||!app.Ready){app=FindObjectOfType<FashionFitApp>();if(Time.realtimeSinceStartupAsDouble>deadline)throw new Exception("App startup timeout");yield return null;}
   app.Player.PrepareForVRTrial();result.fixedPhysics=Physics.simulationMode==SimulationMode.FixedUpdate;Check(result.fixedPhysics,"PhysX is not automatic FixedUpdate");result.defaultsDressed=app.PoseStudio.Wearables[0].Look==5&&app.PoseStudio.Wearables[1].Look==6;Check(result.defaultsDressed,"Pose defaults missing in player");
   var wear=app.PoseStudio.Wearables[0];app.Showroom.SelectOutfitTarget(1);app.Showroom.WearHat(1);yield return new WaitForSecondsRealtime(.7f);var hat=app.Showroom.Hats[1];var head=wear.Rig.Avatar.FindJoint("Head");Vector3 relative=head.InverseTransformPoint(hat.transform.position);head.localRotation*=Quaternion.Euler(0,25,0);yield return null;result.headFollow=Vector3.Distance(relative,head.InverseTransformPoint(hat.transform.position))<.001f;Check(result.headFollow,"Hat does not follow posed head");app.PoseStudio.ResetPose(0);
   hat.ReturnToDisplay();hat.Elastic.SetMaterial(MembraneMaterial.Presets[0]);hat.Elastic.SetSize(1);hat.Elastic.ResetShape();yield return null;hat.transform.position=new Vector3(-.5f,1.9f,.7f);Physics.SyncTransforms();
   var target=hat.GetComponent<RunwayVRGrabTarget>();Vector3 a,b;Extremes(hat.Elastic,out a,out b);object left=new object(),right=new object();Check(!target.TryAcquire(new object(),a+Vector3.up*.5f,Quaternion.identity),"Distant hat grip accepted");Check(target.TryAcquire(left,a,Quaternion.identity)&&target.TryAcquire(right,b,Quaternion.identity),"Two-hand hat acquisition failed");result.twoHandHat=target.OwnerCount==2&&hat.Elastic.GrabCount==2;Check(result.twoHandHat,"Hat patches not owned by both hands");
   double end=Time.realtimeSinceStartupAsDouble+1.6;while(Time.realtimeSinceStartupAsDouble<end){target.DragOwned(left,a-Vector3.right*.065f,Quaternion.identity);target.DragOwned(right,b+Vector3.right*.065f,Quaternion.identity);Record();yield return null;}
   result.hatOffset=hat.Elastic.MaximumOffset;Check(hat.Elastic.Reading.tensileStrain>.003f,"Hat not stretched in player");target.Release(left,false);result.independentRelease=target.OwnerCount==1&&hat.IsHeld;Check(result.independentRelease,"One release lost remaining owner");float y=hat.transform.position.y;target.Release(right,true);yield return new WaitForSecondsRealtime(1.2f);result.dropM=y-hat.transform.position.y;result.gravity=hat.GetComponent<Rigidbody>().useGravity&&result.dropM>.1f;Check(result.gravity,"Hat did not fall through real PhysX updates");yield return new WaitForSecondsRealtime(4);result.hatRecovered=hat.Elastic.MaximumOffset;result.hatRecovery=result.hatRecovered<result.hatOffset*.05f;Check(result.hatRecovery,"Hat did not recover in player time");hat.ReturnToDisplay();
   wear.Wear(2);yield return new WaitForSecondsRealtime(1);Vector3[] baseline=wear.Surface.MeshAt(0).vertices;Extremes(wear.Surface,out a,out b);target=wear.Surface.GetComponent<RunwayVRGrabTarget>();left=new object();right=new object();Check(target.TryAcquire(left,a,Quaternion.identity)&&target.TryAcquire(right,b,Quaternion.identity),"Pose cloth acquisition failed");result.twoHandCloth=target.OwnerCount==2;Check(result.twoHandCloth,"Pose cloth lacks two-hand ownership");end=Time.realtimeSinceStartupAsDouble+1.5;
   while(Time.realtimeSinceStartupAsDouble<end){target.DragOwned(left,a-Vector3.right*.07f,Quaternion.identity);target.DragOwned(right,b+Vector3.right*.07f,Quaternion.identity);Record();yield return null;}
   result.clothError=Error(wear.Surface.MeshAt(0).vertices,baseline);Check(result.clothError>.001f,"Pose cloth did not deform");target.Release(left,false);Check(target.OwnerCount==1&&wear.Surface.GrabCount==1,"Pose cloth lost second grip");target.Release(right,false);yield return new WaitForSecondsRealtime(5);result.clothRecovered=Error(wear.Surface.MeshAt(0).vertices,baseline);result.clothRecovery=result.clothRecovered<result.clothError*.2f;Check(result.clothRecovery,"Pose cloth did not recover");
   app.Showroom.SelectOutfitTarget(1);app.Showroom.WearHat(3);app.Showroom.SelectOutfitTarget(2);app.Showroom.WearHat(4);app.PoseStudio.Wearables[0].Wear(3);var arm=app.PoseStudio.Wearables[1].Rig.Avatar.FindJoint("RightArm");Quaternion original=arm.localRotation;end=Time.realtimeSinceStartupAsDouble+3;double start=Time.realtimeSinceStartupAsDouble;
   while(Time.realtimeSinceStartupAsDouble<end){arm.localRotation=original*Quaternion.Euler(0,0,Mathf.Sin((float)(Time.realtimeSinceStartupAsDouble-start))*15);Record();yield return null;}
   app.PoseStudio.ResetPose(1);yield return new WaitForSecondsRealtime(.3f);Capture();Check(result.exceptions==0,"Unity errors in player");
  }
  void Record(){times.Add(Time.unscaledDeltaTime*1000);foreach(var wear in app.PoseStudio.Wearables)result.maxPoseUpdateMs=Math.Max(result.maxPoseUpdateMs,wear.Milliseconds);}
  static void Extremes(ElasticSurface s,out Vector3 a,out Vector3 b){Vector3[] v=s.MeshAt(0).vertices;int l=0,r=0;for(int i=1;i<v.Length;i++){if(v[i].x<v[l].x)l=i;if(v[i].x>v[r].x)r=i;}a=s.transform.TransformPoint(v[l]);b=s.transform.TransformPoint(v[r]);}
  static float Error(Vector3[] a,Vector3[] b){float e=0;for(int i=0;i<a.Length;i++)e+=(a[i]-b[i]).sqrMagnitude;return Mathf.Sqrt(e/a.Length);}
  void Save(){if(times.Count>0){float sum=0;foreach(float t in times)sum+=t;result.meanFrameMs=sum/times.Count;times.Sort();result.p95FrameMs=times[Math.Min(times.Count-1,(int)(times.Count*.95f))];}File.WriteAllText(Path.Combine(output,"player.json"),JsonUtility.ToJson(result,true));Debug.Log("POSE_MATERIAL_PLAYER "+JsonUtility.ToJson(result));}
  void Capture(){var c=app.Player.View;c.rect=new Rect(0,0,1,1);c.transform.position=new Vector3(2.2f,1.55f,1.25f);c.transform.LookAt(new Vector3(2.2f,1,-1.9f));var rt=new RenderTexture(1400,1100,24);var tex=new Texture2D(1400,1100,TextureFormat.RGB24,false);var old=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1400,1100),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(output,"PosePlayer.png"),tex.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=old;Destroy(tex);Destroy(rt);}}
  void OnDestroy(){Application.logMessageReceived-=Log;}
 }
}
